<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Launch teaser</title>
<script src="https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js"></script>
<style>body{margin:0;background:#111;color:#fafafa;font-family:sans-serif}
#main{position:relative;width:1920px;height:1080px;overflow:hidden;background:#000}
#screen{position:absolute;inset:0;background:#111}
/* ---- yt-screen-warp (from compositions/components/yt-screen-warp.html) ---- */
.yt-screen-warp3d{transform:perspective(1400px) rotateY(-3.5deg) rotateX(1.6deg)}
.yt-screen-fx{position:absolute;inset:0;pointer-events:none;opacity:0;
background:
/* sheen */
linear-gradient(115deg,rgba(255,255,255,.09) 0%,transparent 30%),
/* scanlines */
repeating-linear-gradient(0deg,rgba(0,0,0,.1) 0 1px,transparent 1px 3px),
/* pixel grid */
repeating-linear-gradient(90deg,rgba(0,0,0,.06) 0 1px,transparent 1px 4px);
box-shadow:inset 0 0 90px rgba(0,0,0,.4),inset 0 0 8px rgba(0,0,0,.5)}
</style>
</head>
<body>
<div id="main" data-composition-id="main" data-width="1920" data-height="1080" data-duration="10">
<div id="screen" class="yt-screen-warp3d">
<h1 id="title-card" class="clip" data-start="0" data-duration="3" data-track-index="1">Launch</h1>
<p id="caption-1" class="clip" data-start="3" data-duration="4" data-track-index="2">Welcome</p>
<div class="yt-screen-fx" id="screen-fx"></div>
</div>
</div>
<script>
window.__timelines = window.__timelines || {};
var tl = gsap.timeline({ paused: true });
// screen effect is on for the whole composition: lit from the first frame, never switched off
tl.set("#screen-fx", { opacity: 1 }, 0);
tl.to({}, { duration: 10 }, 0);
window.__timelines["main"] = tl;
</script>
</body>
</html>

